    static let packets: [SanctuaryPacketMetadata] = {
        guard let data = json.data(using: .utf8),
              let decoded = try? JSONDecoder().decode([SanctuaryPacketMetadata].self, from: data) else {
            return []
        }
        return decoded
    }()

    static let byClassName: [String: SanctuaryPacketMetadata] = {
        var result: [String: SanctuaryPacketMetadata] = [:]
        for packet in packets { result[packet.className] = packet }
        return result
    }()

    static func metadata(for name: String) -> SanctuaryPacketMetadata? { byClassName[name] }
}
